			matched = true
		}
	}
	if !matched {
		return errBadSignature
	}
	d := now.Sub(time.Unix(t, 0))
	if d < 0 {
		d = -d
	}
	if d > tolerance {
		return errors.New("timestamp outside tolerance")
	}
	return nil
